function icon(name){return `<svg viewBox="0 0 24 24" aria-hidden="true" fill="none" stroke="currentColor" stroke-width="1.75" stroke-linecap="round" stroke-linejoin="round">${ICON_PATHS[name]||ICON_PATHS.mod}</svg>`}
function esc(v){return String(v??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]))}
function safeImg(v){const raw=String(v||'');if(raw.startsWith('data:image/'))return raw;try{const u=new URL(raw);return u.protocol==='https:'?u.href:''}catch{return ''}}
function providerName(id){return PROVIDER_NAMES[id]||providerCatalog.find(p=>p.id===id)?.name||id||'Unknown source'}
function providerInfo(id){return providerCatalog.find(p=>p.id===id)||null}
function providerReady(p){return !p?.credential||!!p.credentialConfigured}
function providerTypeIcon(p){if((p?.projectTypes||[]).includes('modpack'))return'pack';if((p?.projectTypes||[]).includes('plugin'))return'gear';if(p?.group==='Bedrock')return'bedrock';return'globe'}
function fmtBytes(n){n=Number(n)||0;if(n<1024)return`${n} B`;if(n<1048576)return`${(n/1024).toFixed(1)} KB`;if(n<1073741824)return`${(n/1048576).toFixed(1)} MB`;return`${(n/1073741824).toFixed(2)} GB`}
function fmtNum(n){n=Number(n)||0;if(n>=1e9)return`${(n/1e9).toFixed(1)}B`;if(n>=1e6)return`${(n/1e6).toFixed(1)}M`;if(n>=1e3)return`${(n/1e3).toFixed(1)}K`;return n.toLocaleString()}
function showToast(message,error=false){const el=document.getElementById('toast');el.textContent=message;el.classList.toggle('error',error);el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),4000)}
async function api(path,options={}){const headers=new Headers(options.headers||{});headers.set('X-MMV-Token',TOKEN);if(options.body&&!(options.body instanceof FormData))headers.set('Content-Type','application/json');const res=await fetch(path,{...options,headers});let body={};try{body=await res.json()}catch{}if(!res.ok)throw new Error(body.error||`${res.status} ${res.statusText}`);return body}
async function openExternal(value,isPath=false){try{await api('/api/open',{method:'POST',body:JSON.stringify(isPath?{path:value}:{url:value})})}catch(err){showToast(`Could not open: ${err.message}`,true)}}

