function renderNav(){const root=document.getElementById('nav');root.innerHTML=NAV.map(([id,label,ic])=>`<button data-nav="${id}" class="${id==='home'?'active':''}"><span>${icon(ic)}</span><span>${esc(label)}</span></button>`).join('');root.onclick=e=>{const b=e.target.closest('[data-nav]');if(b)navigate(b.dataset.nav)}}
function navigate(id){if(id==='amazing'||id==='browser')id='mods';if(!PAGE_COPY[id])id='home';document.querySelectorAll('.view').forEach(v=>v.classList.toggle('active',v.dataset.view===id));document.querySelectorAll('[data-nav]').forEach(b=>b.classList.toggle('active',b.dataset.nav===id));document.getElementById('pageTitle').textContent=PAGE_COPY[id][0];document.getElementById('pageSubtitle').textContent=PAGE_COPY[id][1];history.replaceState(null,'',`?token=${encodeURIComponent(TOKEN)}#${id}`);if(id==='mods'&&!document.getElementById('modResults').children.length)modsSearch();if(id==='updater')syncUpdaterTargets();if(id==='doctor'){syncDoctorTargets();loadDoctorTools()}if(id==='conversion')loadConversionStudio();if(id==='porting'){syncPortingTargets();loadPortingAtlas();loadPortingEnvironment();loadPortingWorkspaces()}if(id==='repair')loadRepairLab();if(id==='testgrid')window.TestGridStudio?.activate();if(id==='creators'){loadCreatorChannels();loadCreatorArchive();loadTranscriptionStatus();}if(id==='manager'){if(window.OmniManager&&typeof window.OmniManager.activate==='function')window.OmniManager.activate();else refreshManager();window.OmniManagerPolish?.decorate();}if(id==='settings')loadSettings()}

function cardClass(item){const tags=item.tags||[];if(tags.some(x=>['magic','cute','fairy'].includes(x)))return'pink';if(tags.some(x=>['vehicles','water'].includes(x)))return'blue';if(tags.some(x=>['railroads','vintage','kitchen'].includes(x)))return'gold';return''}
function providerFromCatalogItem(item){const source=String(item.source||'').toLowerCase().replace(/[^a-z0-9]+/g,'');let host='';try{host=new URL(item.url||'').hostname.toLowerCase().replace(/^www\./,'')}catch{}for(const p of providerCatalog){const id=String(p.id||'').toLowerCase(),name=String(p.name||'').toLowerCase().replace(/[^a-z0-9]+/g,'');if(source&&(source.includes(id.replace(/[^a-z0-9]+/g,''))||source.includes(name)))return p.id;try{const providerHost=new URL(p.homeUrl||'').hostname.toLowerCase().replace(/^www\./,'');if(host&&providerHost&&(host===providerHost||host.endsWith(`.${providerHost}`)||providerHost.endsWith(`.${host}`)))return p.id}catch{}}return''}
function catalogProject(item,kind){const provider=providerFromCatalogItem(item);if(!provider)return null;let id=item.projectId||item.id||'',slug=item.projectId||item.id||'';try{const u=new URL(item.url||'');const parts=u.pathname.split('/').filter(Boolean);if(provider==='modrinth'&&parts.length)id=slug=item.projectId||parts[parts.length-1];else if(provider==='github'&&parts.length>=2)id=slug=`${parts[0]}/${parts[1]}`;else if(['spigot','builtbybit'].includes(provider)){const n=parts.find(x=>/^\d+$/.test(x));if(n)id=slug=n}else if(['hangar','planetminecraft','mcpedl','bukkitdev','moddb','curseforge'].includes(provider)&&parts.length)slug=item.projectId||parts[parts.length-1]}catch{}return{provider,id,slug,title:item.name,summary:item.desc,pageUrl:item.url,projectType:item.install||kind||'mod',author:item.author,iconUrl:item.image||item.iconUrl||''}}
function catalogCard(item,kind){const image=safeImg(item.image||item.iconUrl||'');const flavor=item.icon||(kind==='cit'?'pack':kind==='furniture'?'chair':kind==='bedrock'?'bedrock':'mod'),project=catalogProject(item,kind),key=project?cacheProject(project):'';return `<article class="card item-card"><div class="item-top"><div class="item-icon ${cardClass(item)}">${image?`<img src="${esc(image)}" alt="">`:icon(flavor)}</div><div class="item-title"><h3>${esc(item.name)}</h3><div class="meta"><span class="tag source">${esc(item.source)}</span>${item.favorite?'<span class="tag favorite">Cozy pick</span>':''}<span>${esc(item.author||'')}</span></div></div></div><div class="desc">${esc(item.desc)}</div>${item.compat?`<div class="compat">${esc(item.compat)}</div>`:''}<div class="meta">${(item.tags||[]).slice(0,6).map(t=>`<span class="tag">${esc(t)}</span>`).join('')}</div><div class="item-actions">${item.projectId?`<button class="btn primary small" data-install-project="${esc(item.projectId)}" data-install-kind="${esc(item.install||'mod')}">${icon('download')} Install</button>`:''}${key?`<button class="btn small" data-project-details="${esc(key)}">${icon('search')} View in Vault</button>`:`<button class="btn small" data-catalog-search="${esc(item.name)}">${icon('search')} Find in Mods</button>`}</div></article>`}
function wireLegacy(root){root.querySelectorAll('[data-open]').forEach(b=>b.onclick=()=>openExternal(b.dataset.open));root.querySelectorAll('[data-install-project]').forEach(b=>b.onclick=()=>installProject(b.dataset.installProject,b.dataset.installKind,b));root.querySelectorAll('[data-project-details]').forEach(b=>b.onclick=()=>openProjectDetails(b.dataset.projectDetails));root.querySelectorAll('[data-catalog-search]').forEach(b=>b.onclick=()=>{document.getElementById('modQuery').value=b.dataset.catalogSearch;activeCategory='all';renderCategoryStrip();navigate('mods');modsSearch()})}
