function renderCit(){const q=document.getElementById('citQuery').value.trim().toLowerCase(),mood=document.getElementById('citMood').value,arr=CIT_PACKS.filter(x=>(mood==='all'||x.tags.includes(mood))&&(!q||[x.name,x.author,x.source,x.desc,...x.tags].join(' ').toLowerCase().includes(q)));document.getElementById('citCount').textContent=`${arr.length} curated CIT entries`;const grid=document.getElementById('citGrid');grid.innerHTML=arr.map(x=>catalogCard(x,'cit')).join('')||'<div class="card empty">No matching CIT packs.</div>';wireLegacy(grid)}
