function renderBedrock(){const q=document.getElementById('bedrockQuery').value.trim().toLowerCase(),style=document.getElementById('bedrockStyle').value,arr=BEDROCK_PACKS.filter(x=>(style==='all'||x.tags.includes(style))&&(!q||[x.name,x.author,x.source,x.desc,...x.tags].join(' ').toLowerCase().includes(q)));document.getElementById('bedrockCount').textContent=`${arr.length} curated Bedrock entries`;const grid=document.getElementById('bedrockGrid');grid.innerHTML=arr.map(x=>catalogCard(x,'bedrock')).join('')||'<div class="card empty">No matching Bedrock packs.</div>';wireLegacy(grid)}

function cacheProject(p){const key=`${p.provider||'project'}:${p.id||p.slug||p.title}:${Math.abs(hashText(JSON.stringify([p.title,p.pageUrl,p.dateUpdated])))}`;projectCache.set(key,p);return key}
function hashText(s){let h=2166136261;for(let i=0;i<s.length;i++){h^=s.charCodeAt(i);h=Math.imul(h,16777619)}return h|0}
function installActionLabel(type,detail=false){const labels={skin:'Save skin',shader:'Install shader',resourcepack:'Install resource pack',datapack:'Install data pack',plugin:'Install plugin',world:'Install world',addon:'Install / import add-on',modpack:'Install modpack',tool:'Install tool',mod:'Install compatible mod'};const label=labels[type]||'Install compatible';return detail&&type==='mod'?`${label} build`:label}
function projectCard(p){const key=cacheProject(p),gallery=safeImg((p.gallery||[])[0]),logo=safeImg(p.iconUrl),avatar=safeImg(p.authorAvatarUrl),media=gallery||logo;const variants=(p.providers||[p.provider]).map(x=>`<span>${esc(providerName(x))}</span>`).join('');const tags=(p.categories||[]).slice(0,6);return `<article class="card project-card"><div class="project-media">${media?`<img src="${esc(media)}" alt="${esc(p.title)} preview" loading="lazy" referrerpolicy="no-referrer">`:`<div class="fallback-art">${icon(p.projectType==='resourcepack'?'pack':'mod')}</div>`}${logo?`<img class="project-logo" src="${esc(logo)}" alt="${esc(p.title)} icon" loading="lazy" referrerpolicy="no-referrer">`:''}<span class="project-source">${esc(providerName(p.provider))}</span></div><div class="project-body"><div class="project-title-line"><h3>${esc(p.title)}</h3><span class="tag">${esc(p.projectType||'project')}</span></div><div class="author-line">${avatar?`<img class="author-avatar" src="${esc(avatar)}" alt="${esc(p.author||'creator')} avatar" loading="lazy" referrerpolicy="no-referrer">`:`<span class="author-avatar fallback-art">${icon('mod')}</span>`}<span>${esc(p.author||'Unknown creator')}</span><div class="source-variants">${variants}</div></div><div class="project-desc">${esc(p.summary||'')}</div><div class="meta">${tags.map(t=>`<span class="tag">${esc(t)}</span>`).join('')}</div><div class="project-stats">${p.downloads?`<span><b>${fmtNum(p.downloads)}</b> uses</span>`:''}${p.followers?`<span><b>${fmtNum(p.followers)}</b> followers</span>`:''}${p.dateUpdated?`<span>updated ${esc(String(p.dateUpdated).slice(0,10))}</span>`:''}</div>${p.reason?`<div class="compat">${esc(p.reason)}</div>`:''}<div class="project-actions">${p.installable?`<button class="btn primary small" data-provider-install="${esc(p.provider)}" data-provider-id="${esc(p.id)}" data-provider-slug="${esc(p.slug||'')}" data-page-url="${esc(p.pageUrl||'')}" data-project-type="${esc(p.projectType||'mod')}">${icon('download')} ${esc(installActionLabel(p.projectType||'mod'))}</button>`:''}<button class="btn small" data-project-details="${esc(key)}">${icon('search')} Details</button></div></div></article>`}
function wireProjectGrid(root){root.querySelectorAll('[data-project-details]').forEach(b=>b.onclick=()=>openProjectDetails(b.dataset.projectDetails));root.querySelectorAll('[data-provider-install]').forEach(b=>b.onclick=()=>installUnified(b))}
async function openProjectDetails(key){
  const p=projectCache.get(key);if(!p)return;
  const modal=document.getElementById('projectModal'),root=document.getElementById('projectModalContent');
  modal.classList.add('open');modal.setAttribute('aria-hidden','false');document.body.classList.add('modal-open');
  root.innerHTML=`<div class="project-detail-loading"><div class="eyebrow">${esc(providerName(p.provider))}</div><h2 id="projectModalTitle">${esc(p.title)}</h2><p>Loading native project metadata, authors, media, versions and compatibility from the integrated provider…</p></div>`;
  try{
    const q=new URLSearchParams({provider:p.provider,id:p.id||'',slug:p.slug||'',url:p.pageUrl||''});
    const d=await api(`/api/providers/detail?${q}`);
    renderProjectDetails(p,d);
  }catch(err){
    renderProjectDetails(p,null,err);
  }
}
function renderProjectDetails(p,d,error){
  const root=document.getElementById('projectModalContent');
  const info=d||{};const title=info.title||p.title,summary=info.summary||p.summary||'',description=info.description||summary;
  const gallery=[...(info.gallery||[]),...(p.gallery||[])].map(safeImg).filter(Boolean).filter((x,i,a)=>a.indexOf(x)===i).slice(0,16);
  const logo=safeImg(info.iconUrl||p.iconUrl),hero=gallery[0]||logo;
  const authors=(info.authors||[]).length?info.authors:(p.author?[{name:p.author,avatarUrl:p.authorAvatarUrl}]:[]);
  const versions=(info.versions||[]).slice(0,40),gameVersions=info.gameVersions||p.versions||[],loaders=info.loaders||p.loaders||[];
  const categories=info.categories||p.categories||[];const installable=info.installable??p.installable;
  const provider=info.provider||p.provider;
  const authorsHtml=authors.length?authors.map(a=>{const av=safeImg(a.avatarUrl);return `<div class="author-detail">${av?`<img src="${esc(av)}" alt="${esc(a.name||'creator')} avatar" referrerpolicy="no-referrer">`:`<span class="author-avatar fallback-art">${icon('mod')}</span>`}<div><small>${esc(a.role||'CREATOR')}</small><br><b>${esc(a.name||'Unknown creator')}</b></div></div>`}).join(''):'<div class="empty-inline">Creator identity was not exposed by this provider.</div>';
  const versionHtml=versions.length?versions.map(v=>`<div class="version-row"><div><b>${esc(v.version||v.name||v.id)}</b><small>${esc((v.gameVersions||[]).slice(0,8).join(', ')||'Version metadata')} ${v.loaders?.length?` · ${esc(v.loaders.join(', '))}`:''}${v.dependencies?.length?` · ${v.dependencies.length} dependenc${v.dependencies.length===1?'y':'ies'}`:''}</small></div><div><span>${esc(v.published?String(v.published).slice(0,10):'')}</span>${v.files?.length?`<small>${v.files.length} file${v.files.length===1?'':'s'}</small>`:''}</div></div>`).join(''):'<div class="empty-inline">This provider did not enumerate versions through its current integration.</div>';
  const sourceVariants=(p.providers||[p.provider]).map(x=>`<button class="project-detail-source source-variant-button" data-source-variant="${esc(x)}">${esc(providerName(x))}</button>`).join('');
  root.innerHTML=`<div class="project-detail-hero">${hero?`<img src="${esc(hero)}" alt="${esc(title)} project artwork" referrerpolicy="no-referrer">`:`<div class="fallback-art project-detail-fallback-hero">${icon('mod')}</div>`}<div class="project-detail-heading">${logo?`<img class="project-detail-logo" src="${esc(logo)}" alt="${esc(title)} icon" referrerpolicy="no-referrer">`:''}<div><div class="eyebrow">${esc(providerName(provider))} · ${esc(info.projectType||p.projectType||'project')}</div><h2 id="projectModalTitle">${esc(title)}</h2><p>${esc(p.reason||info.installMode||'Integrated provider project')}</p></div></div></div>
  ${error?`<div class="project-detail-warning"><b>Live detail enrichment hit an error.</b><span>${esc(error.message)}</span><small>The normalized search result remains available below instead of sending you out to a website.</small></div>`:''}
  <div class="project-detail-section"><h3>Creators</h3><div class="project-author-grid">${authorsHtml}</div></div>
  <div class="project-detail-section"><h3>About</h3><div class="project-detail-summary long">${esc(description||'This provider did not expose a long description.')}</div></div>
  ${gallery.length?`<div class="project-detail-section"><h3>Project media</h3><div class="project-detail-gallery">${gallery.map(x=>`<img src="${esc(x)}" alt="${esc(title)} gallery image" loading="lazy" referrerpolicy="no-referrer">`).join('')}</div></div>`:''}
  <div class="project-detail-section"><h3>Compatibility & activity</h3><div class="project-detail-facts"><div class="project-detail-fact"><span>Minecraft versions</span><b>${esc(gameVersions.slice(0,20).join(', ')||'Provider did not enumerate')}</b></div><div class="project-detail-fact"><span>Loaders / platforms</span><b>${esc(loaders.join(', ')||'Any / provider did not enumerate')}</b></div><div class="project-detail-fact"><span>Downloads / uses</span><b>${esc(fmtNum(info.downloads||p.downloads||0))}</b></div><div class="project-detail-fact"><span>Last update</span><b>${esc((info.updated||p.dateUpdated)?String(info.updated||p.dateUpdated).slice(0,10):'Unknown')}</b></div></div></div>
  <div class="project-detail-section"><h3>Categories</h3><div class="meta">${categories.map(t=>`<span class="tag">${esc(t)}</span>`).join('')||'<span class="tag">Uncategorized</span>'}</div></div>
  <div class="project-detail-section"><h3>Versions</h3><div class="version-list">${versionHtml}</div></div>
  <div class="project-detail-section"><h3>Integrated source variants</h3><div class="project-detail-sources">${sourceVariants}</div></div>
  <div class="project-detail-actions">${installable?`<button class="btn primary" id="projectModalInstall">${icon('download')} ${esc(installActionLabel(info.projectType||p.projectType||'mod',true))}</button>`:''}<button class="btn" id="projectModalBrowseProvider">${icon('search')} More from ${esc(providerName(provider))}</button></div>`;
  const browse=document.getElementById('projectModalBrowseProvider');if(browse)browse.onclick=()=>{activeProviders=new Set([provider]);renderProviderStrip();document.getElementById('modQuery').value=title;closeProjectDetails();navigate('mods');modsSearch()};
  root.querySelectorAll('[data-source-variant]').forEach(b=>b.onclick=()=>{activeProviders=new Set([b.dataset.sourceVariant]);renderProviderStrip();document.getElementById('modQuery').value=title;closeProjectDetails();navigate('mods');modsSearch()});
  const install=document.getElementById('projectModalInstall');if(install){install.dataset.providerInstall=provider;install.dataset.providerId=info.id||p.id;install.dataset.providerSlug=info.slug||p.slug||'';install.dataset.projectType=info.projectType||p.projectType||'mod';install.dataset.pageUrl=info.pageUrl||p.pageUrl||'';install.onclick=()=>installUnified(install)}
}
function closeProjectDetails(){const modal=document.getElementById('projectModal');modal.classList.remove('open');modal.setAttribute('aria-hidden','true');document.body.classList.remove('modal-open')}
async function installUnified(button){const old=button.innerHTML;button.disabled=true;const type=button.dataset.projectType;button.textContent=type==='skin'?'Saving skin…':'Installing…';try{const target=type==='resourcepack'?'resourcepacks':type==='shader'?'shaderpacks':type==='plugin'?'plugins':type==='datapack'?'datapacks':type==='world'?'worlds':type==='mod'?'mods':type==='skin'?'skins':'downloads';const result=await api('/api/providers/install',{method:'POST',body:JSON.stringify({provider:button.dataset.provider,id:button.dataset.providerId,slug:button.dataset.providerSlug,pageUrl:button.dataset.pageUrl||'',gameVersion:currentSettings?.gameVersion,loader:currentSettings?.loader,target})});showToast(type==='skin'?`Saved skin from ${providerName(button.dataset.provider)}`:`Installed from ${providerName(button.dataset.provider)}`);if(result.path)console.info(result.path)}catch(err){showToast(err.message,true)}finally{button.disabled=false;button.innerHTML=old}}

async function loadTaxonomy(){try{const data=await api('/api/taxonomy');taxonomy=data.categories||[];renderCategoryStrip();renderHomeCategories();renderHomeStats()}catch(err){document.getElementById('modStatus').textContent=err.message}}
function renderCategoryStrip(){const root=document.getElementById('modCategoryStrip');root.innerHTML=taxonomy.map(c=>`<button class="category-chip ${c.id===activeCategory?'active':''}" data-category="${esc(c.id)}"><span>${icon(c.icon||'mod')}</span><b>${esc(c.name)}</b><small>${esc(c.group||'')}</small></button>`).join('');root.querySelectorAll('[data-category]').forEach(b=>b.onclick=()=>{activeCategory=b.dataset.category;renderCategoryStrip();const cat=taxonomy.find(x=>x.id===activeCategory);if(cat&&activeCategory!=='all'&&!document.getElementById('modQuery').value.trim())document.getElementById('modQuery').value='';modsSearch()})}
function providerSupportsCurrentType(p){const t=document.getElementById('modType')?.value||'all';return t==='all'||(p.projectTypes||[]).includes(t)}
function renderProviderStrip(){
  const root=document.getElementById('providerStrip');if(!root)return;
  const needle=providerFilterText.trim().toLowerCase(),type=document.getElementById('modType')?.value||'all';
  const visible=providerCatalog.filter(p=>!needle||[p.name,p.group,p.description,...(p.projectTypes||[])].join(' ').toLowerCase().includes(needle));
  let lastGroup='';const parts=[];
  for(const p of visible){
    if(p.group!==lastGroup){lastGroup=p.group;parts.push(`<span class="provider-group-label">${esc(lastGroup)}</span>`)}
    const on=activeProviders.has(p.id),health=providerHealth[p.id],ready=providerReady(p),relevant=providerSupportsCurrentType(p);
    parts.push(`<button class="provider-chip ${on?'active':''} ${ready?'':'credential-needed'} ${relevant?'':'type-irrelevant'}" data-provider-toggle="${esc(p.id)}" title="${esc(relevant?(p.description||''):`Not used for the selected ${document.getElementById('modType')?.selectedOptions?.[0]?.textContent||'content'} filter`)}">${icon(providerTypeIcon(p))}<span>${esc(p.name)}</span><i class="provider-health ${esc(health?.status||'idle')}"></i><b>${relevant?(on?'ON':'OFF'):'N/A'}</b>${ready?'':`<em>key</em>`}</button>`)
  }
  root.innerHTML=parts.join('')||'<span class="empty-inline">No integrated providers match that source filter.</span>';
  root.querySelectorAll('[data-provider-toggle]').forEach(b=>b.onclick=()=>{const id=b.dataset.providerToggle;activeProviders.has(id)?activeProviders.delete(id):activeProviders.add(id);renderProviderStrip();modsSearch()});
  const relevant=providerCatalog.filter(providerSupportsCurrentType),selectedRelevant=relevant.filter(p=>activeProviders.has(p.id)).length,healthy=relevant.filter(p=>providerHealth[p.id]?.status==='ok').length;
  const summary=document.getElementById('providerSelectionSummary');if(summary)summary.textContent=`${selectedRelevant}/${relevant.length} relevant selected · ${healthy} healthy · ${providerCatalog.length} integrated`;
  renderProviderPresets();
}
function renderProviderPresets(){
  const root=document.getElementById('providerPresets');if(!root)return;
  const presets=[['ready','Ready sites'],['all','Every site'],['curated','Curated discovery'],['client','Java client'],['packs','Data + visual packs'],['shaders','Shaders'],['skins','Skins'],['worlds','Maps + worlds'],['plugins','Plugins'],['modpacks','Modpacks'],['bedrock','Bedrock'],['community','Community'],['markets','Marketplaces'],['none','None']];
  root.innerHTML=presets.map(([id,label])=>`<button class="btn small" data-provider-preset="${id}">${esc(label)}</button>`).join('');
  root.querySelectorAll('[data-provider-preset]').forEach(b=>b.onclick=()=>applyProviderPreset(b.dataset.providerPreset));
}
function applyProviderPreset(mode){
  const include=p=>{if(mode==='all')return true;if(mode==='ready')return providerReady(p);if(mode==='curated')return p.group==='Curated discovery';if(mode==='client')return (p.projectTypes||[]).some(x=>['mod','resourcepack','shader','datapack'].includes(x));if(mode==='packs')return (p.projectTypes||[]).some(x=>['resourcepack','shader','datapack'].includes(x));if(mode==='shaders')return (p.projectTypes||[]).includes('shader');if(mode==='skins')return (p.projectTypes||[]).includes('skin');if(mode==='worlds')return (p.projectTypes||[]).includes('world');if(mode==='plugins')return (p.projectTypes||[]).includes('plugin');if(mode==='modpacks')return (p.projectTypes||[]).includes('modpack');if(mode==='bedrock')return p.group==='Bedrock'||(p.projectTypes||[]).includes('addon');if(mode==='community')return ['Community','General community','Curated utilities','Curated discovery'].includes(p.group);if(mode==='markets')return p.group==='Marketplaces';return false};
  activeProviders=new Set(mode==='none'?[]:providerCatalog.filter(include).map(p=>p.id));renderProviderStrip();modsSearch();
}
function modSearchStateSignature(){return JSON.stringify({q:document.getElementById('modQuery')?.value.trim()||'',category:activeCategory,type:document.getElementById('modType')?.value||'all',game:document.getElementById('modGameVersion')?.value.trim()||'',loader:document.getElementById('modLoader')?.value||'any',sort:document.getElementById('modSort')?.value||'relevance',sources:[...activeProviders].sort()})}
function modProjectIdentity(p){return `${p.provider||''}:${p.id||p.pageUrl||p.slug||p.title||''}`.toLowerCase()}
function renderModResultSet(){const grid=document.getElementById('modResults');grid.classList.toggle('list-mode',modViewMode==='list');grid.innerHTML=modSearchResults.map(projectCard).join('');if(!grid.children.length)grid.innerHTML='<div class="card empty">No provider results. Try another category, site selection, version, or loader.</div>';wireProjectGrid(grid);wireLegacy(grid);const summary=document.getElementById('modLoadedSummary');if(summary)summary.textContent=`${modSearchResults.length} unique projects loaded in full · ${modViewMode==='list'?'list':'grid'} view`}
function setModViewMode(mode){modViewMode=mode==='list'?'list':'grid';try{localStorage.setItem('mmv-mod-view',modViewMode)}catch{}document.getElementById('modViewGrid')?.classList.toggle('active',modViewMode==='grid');document.getElementById('modViewList')?.classList.toggle('active',modViewMode==='list');renderModResultSet()}
function resetModBrowser(){activeCategory='all';providerFilterText='';const pf=document.getElementById('providerFilter');if(pf)pf.value='';document.getElementById('modQuery').value='';document.getElementById('modType').value='all';document.getElementById('modGameVersion').value=currentSettings?.gameVersion||'1.21.1';document.getElementById('modLoader').value=['fabric','forge','neoforge','quilt'].includes(currentSettings?.loader)?currentSettings.loader:'any';document.getElementById('modSort').value='relevance';activeProviders=new Set(currentSettings?.enabledSources||providerCatalog.filter(p=>p.defaultEnabled).map(p=>p.id));renderCategoryStrip();renderProviderStrip();modsSearch()}
function renderResultSourceFacets(counts={}){lastSourceCounts=counts||{};const root=document.getElementById('modSourceFacets');if(!root)return;const entries=Object.entries(lastSourceCounts).filter(([,n])=>Number(n)>0).sort((a,b)=>Number(b[1])-Number(a[1])||providerName(a[0]).localeCompare(providerName(b[0])));root.innerHTML=entries.length?`<span>Live source coverage</span>${entries.map(([id,n])=>`<button class="source-facet" data-result-source="${esc(id)}"><b>${esc(providerName(id))}</b><i>${fmtNum(n)}</i></button>`).join('')}`:'';root.querySelectorAll('[data-result-source]').forEach(b=>b.onclick=()=>{activeProviders=new Set([b.dataset.resultSource]);renderProviderStrip();modsSearch()})}

function offlineSeedsForCategory(id){if(id==='cit')return CIT_PACKS.slice(0,8);if(id==='furniture')return FURNITURE_MODS.slice(0,8);if(id==='cute')return [...CIT_PACKS.filter(x=>x.tags.includes('cute')).slice(0,4),...FURNITURE_MODS.filter(x=>x.tags.includes('cute')).slice(0,4)];return MOD_DISCOVERY_SEEDS.filter(x=>x.category===id).slice(0,8)}
function renderHomeCategories(){const root=document.getElementById('homeCategoryGrid');if(!root)return;const prefs=(currentSettings?.preferredTags||[]).map(x=>String(x).toLowerCase()),score=c=>{const hay=[c.name,...(c.queries||[])].join(' ').toLowerCase();let n=String(c.group||'').toLowerCase().includes('live')?2:0;for(const pref of prefs)for(const word of pref.split(/\s+/))if(word.length>=3&&hay.includes(word))n+=8;return n};const cats=taxonomy.filter(c=>c.id!=='all').map((c,i)=>({c,i,s:score(c)})).sort((a,b)=>b.s-a.s||a.i-b.i).slice(0,18).map(x=>x.c);root.innerHTML=cats.map(c=>`<button class="card category-lane" data-home-category="${esc(c.id)}"><span class="category-lane-icon">${icon(c.icon||'pack')}</span><span><b>${esc(c.name)}</b><small>${esc(c.group||'Live category')}</small></span><i>${icon('search')}</i></button>`).join('');root.querySelectorAll('[data-home-category]').forEach(b=>b.onclick=()=>{activeCategory=b.dataset.homeCategory;renderCategoryStrip();navigate('mods');modsSearch()})}
async function modsSearch(loadMore=false){
  const btn=document.getElementById('modSearchBtn'),moreBtn=document.getElementById('modLoadMoreBtn'),grid=document.getElementById('modResults'),status=document.getElementById('modStatus'),notice=document.getElementById('providerErrors'),moreWrap=document.getElementById('modLoadMoreWrap'),moreHint=document.getElementById('modLoadMoreHint');
  if(!activeProviders.size){status.textContent='Select at least one provider or use a provider preset.';notice.textContent='';grid.innerHTML='<div class="card empty">Choose the Minecraft sites you want to search above.</div>';moreWrap.hidden=true;return}
  const signature=modSearchStateSignature();
  if(!loadMore||signature!==modSearchSignature){modSearchSignature=signature;modSearchOffset=0;modSearchResults=[];modSearchSeen=new Set();modSearchHasMore=false;lastSourceCounts={};renderResultSourceFacets({})}
  btn.disabled=true;if(moreBtn)moreBtn.disabled=true;
  if(loadMore){if(moreHint)moreHint.textContent='Expanding every pageable provider and re-ranking the merged window…'}else{status.textContent='Searching enabled providers and merging duplicates…';notice.textContent='';grid.innerHTML='<div class="card loading">Querying live sources, compatibility metadata, project art, and authors…</div>';moreWrap.hidden=true}
  try{
    const params=new URLSearchParams({q:document.getElementById('modQuery').value.trim(),category:activeCategory,type:document.getElementById('modType').value,gameVersion:document.getElementById('modGameVersion').value.trim(),loader:document.getElementById('modLoader').value,sort:document.getElementById('modSort').value,sources:[...activeProviders].join(','),limit:String(modSearchPageSize),offset:String(modSearchOffset)});
    const data=await api(`/api/providers/search?${params}`),sourceCount=Object.keys(data.sources||{}).length,failures=Object.keys(data.errors||{}),cached=Object.keys(data.warnings||{}),mode=data.live===false?'live + cached fallback':'live';renderResultSourceFacets(data.sources||{});
    let added=0;for(const p of data.results||[]){const key=modProjectIdentity(p);if(modSearchSeen.has(key))continue;modSearchSeen.add(key);modSearchResults.push(p);added++}
    const previousOffset=modSearchOffset;modSearchOffset=Number(data.nextOffset??(previousOffset+(data.results||[]).length));modSearchHasMore=!!data.hasMore&&modSearchOffset>previousOffset;
    status.textContent=`${modSearchResults.length} unique projects loaded from ${sourceCount} relevant providers · ${mode} · target ${data.gameVersion||'any'} / ${data.loader||'any'}`;
    const messages=[];if(failures.length)messages.push(`Unavailable: ${failures.map(x=>providerName(x)).join(', ')}`);if(cached.length)messages.push(`Cached fallback: ${cached.map(x=>providerName(x)).join(', ')}`);if(data.skipped&&Object.keys(data.skipped).length)messages.push(`${Object.keys(data.skipped).length} selected sites skipped as irrelevant to this content type`);notice.textContent=messages.join(' · ');
    if(!modSearchResults.length&&failures.length){const fallback=offlineSeedsForCategory(activeCategory);if(fallback.length){grid.innerHTML=`<div class="card outage-fallback full-span"><div class="eyebrow">OFFLINE FALLBACK ONLY</div><b>Live providers could not answer this request.</b><p>These preserved Vault seeds are shown only as a recovery layer. They never replace live ranking when providers are reachable.</p></div>${fallback.map(x=>catalogCard(x,activeCategory)).join('')}`;wireLegacy(grid)}}else{renderModResultSet()}
    moreWrap.hidden=!modSearchHasMore;if(moreHint)moreHint.textContent=modSearchHasMore?`${data.poolTotal||data.total||modSearchResults.length} merged candidates indexed so far · next pass expands the provider window`:(loadMore&&added===0?'No additional unique projects were returned.':'All currently reachable results in the bounded live window are loaded.');
  }catch(err){status.textContent='Universal search failed.';if(!modSearchResults.length){const fallback=offlineSeedsForCategory(activeCategory);grid.innerHTML=fallback.length?`<div class="card outage-fallback full-span"><div class="eyebrow">LIVE SEARCH ERROR · FALLBACK</div><b>${esc(err.message)}</b><p>Showing preserved Vault seeds only until the live index is reachable again.</p></div>${fallback.map(x=>catalogCard(x,activeCategory)).join('')}`:`<div class="card empty">${esc(err.message)}</div>`;wireLegacy(grid)}showToast(err.message,true);moreWrap.hidden=true
  }finally{btn.disabled=false;if(moreBtn)moreBtn.disabled=false}
}

async function loadRecommendations(){const grid=document.getElementById('recommendationGrid'),status=document.getElementById('recommendationStatus');try{const data=await api('/api/recommendations');status.textContent=data.count?`${data.count} live-ranked projects · refreshed ${data.updated?new Date(data.updated).toLocaleString():'pending first refresh'}`:'Recommendation engine is warming up. Use Refresh intelligence to populate it now.';grid.innerHTML=(data.items||[]).slice(0,12).map(projectCard).join('')||'<div class="card empty">Live recommendations will appear after the first provider refresh.</div>';wireProjectGrid(grid);document.getElementById('backgroundStatus').textContent=data.count?`${data.count} recommendations cached`:'Waiting for first provider refresh'}catch(err){status.textContent=err.message}}
async function refreshRecommendations(){const b=document.getElementById('refreshRecommendations'),old=b.innerHTML;b.disabled=true;b.textContent='Refreshing…';try{await api('/api/recommendations/refresh',{method:'POST',body:'{}'});await loadRecommendations();showToast('Recommendation intelligence refreshed from live providers.')}catch(err){showToast(err.message,true)}finally{b.disabled=false;b.innerHTML=old}}
function renderHomeStats(){const browseCount=taxonomy.length?taxonomy.filter(c=>c.id!=='all').length:null;document.getElementById('homeStats').innerHTML=`<div class="stat"><b>${providerCatalog.length||'…'}</b><span>integrated source lanes</span></div><div class="stat"><b>${browseCount===null?'…':`${browseCount}+`}</b><span>live + Vault browse categories</span></div><div class="stat"><b>${CIT_PACKS.length}</b><span>CIT curated seeds</span></div><div class="stat"><b>${FURNITURE_MODS.length+BEDROCK_PACKS.length}</b><span>furniture + Bedrock seeds</span></div>`}

function syncUpdaterTargets(){if(!currentSettings)return;document.getElementById('updateGameVersion').value=currentSettings.gameVersion||'1.21.1';document.getElementById('updateLoader').value=currentSettings.loader==='vanilla'?'fabric':currentSettings.loader}
async function scanUpdates(){const b=document.getElementById('scanUpdates'),list=document.getElementById('updateList');b.disabled=true;b.textContent='Fingerprinting and resolving…';list.innerHTML='<div class="card loading">Hashing local JARs, identifying exact provider files, resolving target-version releases, then searching ports and continuations for gaps…</div>';try{lastUpdatePlan=await api('/api/updater/scan',{method:'POST',body:JSON.stringify({gameVersion:document.getElementById('updateGameVersion').value.trim(),loader:document.getElementById('updateLoader').value})});renderUpdatePlan(lastUpdatePlan);showToast(`Scan complete: ${lastUpdatePlan.safeCount} verified-safe update${lastUpdatePlan.safeCount===1?'':'s'}.`)}catch(err){list.innerHTML=`<div class="card empty">${esc(err.message)}</div>`;showToast(err.message,true)}finally{b.disabled=false;b.innerHTML=`${icon('radar')} Scan every installed mod`}}
function renderUpdatePlan(plan){document.getElementById('updateSummary').innerHTML=[['Safe updates',plan.safeCount,'update'],['Already current',plan.currentCount,'current'],['Review ports/forks',plan.reviewCount,'review'],['Unknown',plan.unknownCount,'unknown']].map(([name,count,cls])=>`<div class="card summary-box"><b>${count}</b><span>${name}</span></div>`).join('');document.getElementById('applySafeUpdates').disabled=!plan.safeCount;const list=document.getElementById('updateList');list.innerHTML=(plan.items||[]).map(updateItemCard).join('')||'<div class="card empty">No mod JARs were found in the configured mods folder.</div>';list.querySelectorAll('[data-project-details]').forEach(b=>b.onclick=()=>openProjectDetails(b.dataset.projectDetails))}
function updateAlternativeCard(a){const key=cacheProject({provider:a.provider,id:a.projectId||a.id,slug:a.projectId||'',title:a.projectTitle,summary:a.reason,pageUrl:a.pageUrl,projectType:'mod'});return `<div class="candidate"><div><strong>${esc(a.projectTitle)}</strong><small>${Math.round((a.confidence||0)*100)}% candidate · ${esc(a.provider)} · ${esc(a.reason)}</small></div><button class="btn small" data-project-details="${esc(key)}">Review in Vault</button></div>`}
function updateItemCard(item){const u=item.safeUpdate;const alts=item.alternatives||[];return `<article class="card update-item"><div class="update-head"><div><h3>${esc(item.installedProject||item.local.metadata?.name||item.local.filename)}</h3><div class="update-file">${esc(item.local.filename)} · ${esc(item.local.metadata?.modId||'unresolved mod id')} · ${fmtBytes(item.local.size)}</div></div><span class="update-status ${esc(item.status)}">${esc(item.status)}</span></div><div class="update-message">${esc(item.message)}</div>${u?`<div class="candidate safe"><div><strong>${esc(u.projectTitle)} ${esc(u.version)}</strong><small>${esc(u.provider)} · ${esc(u.filename)} · ${esc(u.reason)}</small></div><span class="tag">verified safe</span></div>`:''}${alts.slice(0,5).map(updateAlternativeCard).join('')}</article>`}
async function applySafeUpdates(){if(!lastUpdatePlan)return;const b=document.getElementById('applySafeUpdates'),old=b.innerHTML;b.disabled=true;b.textContent='Backing up and updating…';try{const result=await api('/api/updater/apply',{method:'POST',body:JSON.stringify({planId:lastUpdatePlan.id})});showToast(`Updated ${result.count} mod${result.count===1?'':'s'}. Backups preserved.`);await scanUpdates()}catch(err){showToast(`Updater rolled back: ${err.message}`,true)}finally{b.disabled=false;b.innerHTML=old}}

let creatorArchiveView='mods',creatorChannels=[],creatorSuggestions=[],creatorArchiveDebounce=null;
function creatorArchiveParams(mode=creatorArchiveView){const q=document.getElementById('creatorArchiveQuery')?.value.trim()||'',channel=document.getElementById('creatorArchiveChannel')?.value||'',kind=document.getElementById('creatorArchiveKind')?.value||'all',sort=document.getElementById('creatorArchiveSort')?.value||'recommended-desc';const p=new URLSearchParams();if(q)p.set('q',q);if(channel)p.set('channel',channel);if(kind&&kind!=='all')p.set('kind',kind);if(mode==='videos'){p.set('includePending','1');p.set('sort',sort)}else p.set('sort',sort);return p}
function fmtDate(raw){if(!raw)return'Unknown date';const d=new Date(raw);return Number.isNaN(d.getTime())?String(raw).slice(0,10):d.toLocaleDateString(undefined,{year:'numeric',month:'short',day:'numeric'})}
function fmtDuration(sec){sec=Number(sec)||0;if(!sec)return'';const h=Math.floor(sec/3600),m=Math.floor((sec%3600)/60),s=Math.floor(sec%60);return h?`${h}:${String(m).padStart(2,'0')}:${String(s).padStart(2,'0')}`:`${m}:${String(s).padStart(2,'0')}`}
function creatorChannelIdentity(c){const platform=String(c.platform||'youtube').toLowerCase();return c.channelId?`${platform}:${c.channelId}`:c.handle?`${platform}:${String(c.handle).toLowerCase()}`:(c.url||c.title||'')}
function creatorChannelLabel(c){const identity=c.handle||c.channelId||'',platform=String(c.platform||'youtube').toUpperCase();return c.title&&identity?`${c.title} · ${platform} · ${identity}`:(c.title||identity||`${platform} creator`)}
function creatorTierLabel(tier){return({'current-showcases':'Current showcase','current-modded':'Current modded','deep-modded':'Deep modded','historical-gold':'Historical gold','historical-giant':'Historical giant','utility':'Utility'})[tier]||tier||'Recommended'}
function creatorSuggestionVisible(s){const tier=document.getElementById('creatorSuggestionTier')?.value||'all';if(tier==='all')return true;if(tier==='current')return String(s.tier||'').startsWith('current-');if(tier==='historical')return String(s.tier||'').startsWith('historical-');return s.tier===tier}
function renderCreatorSuggestions(){const root=document.getElementById('creatorSuggestionGrid');if(!root)return;const items=creatorSuggestions.filter(creatorSuggestionVisible);root.innerHTML=items.map(creatorSuggestionCard).join('')||'<div class="card empty">No creator recommendations in this tier.</div>';root.querySelectorAll('[data-add-suggestion]').forEach(b=>b.onclick=()=>addCreatorChannel(b.dataset.addSuggestion,b));root.querySelectorAll('[data-open]').forEach(b=>b.onclick=e=>{e.preventDefault();openExternal(b.dataset.open)})}
function creatorSuggestionCard(s){return `<article class="card creator-suggestion-card ${s.tracked?'tracked':''}"><div class="creator-suggestion-head"><div><span class="creator-suggestion-tier">${esc(creatorTierLabel(s.tier))}</span><h3>${esc(s.title)}</h3><small>${esc(String(s.platform||'youtube').toUpperCase())} · ${esc(s.handle||s.channelId||'creator')}</small></div><span class="creator-priority" title="Recommendation priority">${esc(s.priority||0)}</span></div><p class="creator-suggestion-focus">${esc(s.focus||'')}</p><p class="creator-suggestion-why">${esc(s.why||'')}</p><div class="project-actions">${s.tracked?`<button class="btn small success" disabled>${icon('shield')} Following</button>`:`<button class="btn primary small" data-add-suggestion="${esc(s.url)}">${icon('plus')} Follow + sync</button>`}<button class="btn small" data-open="${esc(s.url)}">${icon('external')} Channel</button></div></article>`}
async function loadCreatorChannels(){const root=document.getElementById('creatorChannelGrid');try{const data=await api('/api/creators/channels');creatorChannels=data.channels||[];creatorSuggestions=data.suggestions||[];const select=document.getElementById('creatorArchiveChannel'),prior=select?.value||'';if(select){select.innerHTML='<option value="">All followed channels</option>'+creatorChannels.map(c=>`<option value="${esc(creatorChannelIdentity(c))}">${esc(creatorChannelLabel(c))}${c.paused?' · paused':''}</option>`).join('');if([...select.options].some(o=>o.value===prior))select.value=prior;else select.value=''}root.innerHTML=creatorChannels.map(creatorChannelCard).join('')||'<div class="card empty">No followed channels yet.</div>';root.querySelectorAll('[data-sync-channel]').forEach(b=>b.onclick=()=>syncCreatorArchive(b.dataset.syncChannel,b));root.querySelectorAll('[data-refresh-profile-links]').forEach(b=>b.onclick=()=>refreshCreatorProfileLinksUI(b.dataset.refreshProfileLinks,b));root.querySelectorAll('[data-pause-channel]').forEach(b=>b.onclick=()=>setCreatorChannelPaused(b.dataset.pauseChannel,b.dataset.paused!=='true',b));root.querySelectorAll('[data-remove-channel]').forEach(b=>b.onclick=()=>removeCreatorChannel(b.dataset.removeChannel,b));root.querySelectorAll('[data-open]').forEach(b=>b.onclick=e=>{e.preventDefault();openExternal(b.dataset.open)});renderCreatorSuggestions();renderCreatorArchiveStats()}catch(err){root.innerHTML=`<div class="card empty">${esc(err.message)}</div>`}}
function creatorProfileLinkKindLabel(kind){return({'modpack':'Modpack','mod':'Mod','mod-list':'Mod list','resource-pack':'Resource pack','shader':'Shader','datapack':'Data pack','creator-profile':'Creator profile','link-hub':'Link hub','social':'Social','download':'Download','support':'Support','wishlist':'Wishlist','website':'Website'})[kind]||'Link'}
function creatorProfileLinkIcon(kind){if(kind==='modpack')return'pack';if(kind==='mod'||kind==='mod-list'||kind==='resource-pack'||kind==='shader'||kind==='datapack')return'mod';if(kind==='creator-profile'||kind==='link-hub'||kind==='website')return'globe';if(kind==='download')return'download';return'external'}
function creatorProfileLinksHTML(c){let links=Array.isArray(c.profileLinks)?c.profileLinks.slice():[];if(Array.isArray(c.creatorModpacks)&&c.creatorModpacks.length)links=links.filter(link=>link.kind!=='modpack');if(!links.length&&Array.isArray(c.profileHubUrls))links=c.profileHubUrls.map(url=>({url,label:'Creator link hub',kind:'link-hub'}));const status=c.profileLinksStatus||'pending',stamp=c.profileLinksRefreshedAt?` · refreshed ${fmtDate(c.profileLinksRefreshedAt)}`:'',statusCopy=status==='ready'?'live creator links':status==='cached'?'cached links · provider refresh blocked':status==='seeded'?'curated link hubs · refresh pending':'link discovery pending';if(!links.length)return `<div class="creator-profile-links empty"><div class="creator-profile-links-head"><strong>${icon('globe')} Creator links</strong><span class="creator-profile-status ${esc(status)}">${esc(statusCopy+stamp)}</span></div><p>No public link-in-bio destinations have been discovered yet. The next creator sync will inspect the public profile and supported link hubs automatically.</p>${c.profileLinksError?`<small>${esc(c.profileLinksError)}</small>`:''}</div>`;links.sort((a,b)=>{const weight=k=>({'modpack':0,'mod':1,'mod-list':1,'resource-pack':2,'shader':2,'datapack':2,'creator-profile':3,'link-hub':4,'social':5,'download':6,'support':7,'wishlist':7,'website':8})[k]??8;return weight(a.kind)-weight(b.kind)||String(a.label||a.provider||a.url).localeCompare(String(b.label||b.provider||b.url))});return `<div class="creator-profile-links"><div class="creator-profile-links-head"><strong>${icon('globe')} Creator links</strong><span class="creator-profile-status ${esc(status)}">${esc(`${statusCopy} · ${links.length} found${stamp}`)}</span></div><div class="creator-profile-link-grid">${links.slice(0,12).map(link=>`<button type="button" class="creator-profile-link ${esc(link.kind||'website')}" data-open="${esc(link.url)}" title="Discovered from ${esc(link.evidenceUrl||c.url||'creator profile')}">${icon(creatorProfileLinkIcon(link.kind))}<span><b>${esc(link.label||link.provider||creatorProfileLinkKindLabel(link.kind))}</b><small>${esc(creatorProfileLinkKindLabel(link.kind))}${link.provider?` · ${esc(link.provider)}`:''}</small></span></button>`).join('')}</div>${links.length>12?`<div class="creator-profile-more">+${links.length-12} more discovered links retained in the creator record</div>`:''}${c.profileLinksError?`<div class="creator-profile-warning">Using last-known-good links: ${esc(c.profileLinksError)}</div>`:''}</div>`}
function creatorModpackRelationshipLabel(raw){return({'owner':'Owner','member':'Collaborator','collaborator':'Collaborator','profile':'Creator profile','linked':'Creator linked'})[String(raw||'').toLowerCase()]||'Verified'}
function creatorModpacksHTML(c){const packs=Array.isArray(c.creatorModpacks)?c.creatorModpacks.slice():[],status=c.creatorModpacksStatus||'pending',stamp=c.creatorModpacksRefreshedAt?` · checked ${fmtDate(c.creatorModpacksRefreshedAt)}`:'',providers={};for(const p of packs)providers[p.provider||'Other']=(providers[p.provider||'Other']||0)+1;const providerCopy=Object.entries(providers).map(([name,count])=>`${name} ${count}`).join(' · '),statusCopy=status==='ready'?'verified creator library':status==='partial'?'partially refreshed · cached provider data retained':status==='cached'?'cached creator library':status==='none'?'no verified modpack found':'modpack discovery pending';if(!packs.length)return `<section class="creator-modpack-library empty"><div class="creator-modpack-head"><strong>${icon('pack')} Creator modpacks</strong><span class="creator-modpack-status ${esc(status)}">${esc(statusCopy+stamp)}</span></div><p>No verified CurseForge or Modrinth modpack is attached to this creator yet. Creator Vault keeps checking creator profiles, Linktree-style hubs, and uploader descriptions; it will not invent a pack when provider evidence is missing.</p>${c.creatorModpacksError?`<small>${esc(c.creatorModpacksError)}</small>`:''}</section>`;packs.sort((a,b)=>{const pw=p=>String(p.provider||'').toLowerCase()==='curseforge'?0:String(p.provider||'').toLowerCase()==='modrinth'?1:2,rw=r=>({'owner':0,'member':1,'collaborator':1,'profile':2,'linked':3})[String(r||'').toLowerCase()]??4;return pw(a)-pw(b)||rw(a.relationship)-rw(b.relationship)||(Number(b.downloads||0)-Number(a.downloads||0))||String(a.title||'').localeCompare(String(b.title||''))});return `<details class="creator-modpack-library" ${packs.length<=8?'open':''}><summary><span><strong>${icon('pack')} Creator modpacks</strong><small>${esc(`${packs.length} verified${providerCopy?` · ${providerCopy}`:''}${stamp}`)}</small></span><span class="creator-modpack-status ${esc(status)}">${esc(statusCopy)}</span></summary><div class="creator-modpack-grid">${packs.map(pack=>`<button type="button" class="creator-modpack-card" data-open="${esc(pack.url)}" title="${esc(`${creatorModpackRelationshipLabel(pack.relationship)} · evidence: ${pack.evidenceUrl||pack.providerProfileUrl||c.url||'provider profile'}`)}">${safeImg(pack.iconUrl)?`<img src="${esc(safeImg(pack.iconUrl))}" alt="" referrerpolicy="no-referrer">`:`<span class="creator-modpack-icon">${icon('pack')}</span>`}<span class="creator-modpack-copy"><b>${esc(pack.title||pack.slug||'Verified modpack')}</b><small>${esc(`${pack.provider||'Provider'} · ${creatorModpackRelationshipLabel(pack.relationship)}${pack.downloads?` · ${fmtNum(pack.downloads)} downloads`:''}`)}</small><em>${esc([...(pack.gameVersions||[]).slice(0,2),...(pack.loaders||[]).slice(0,2)].join(' · ')||(pack.updated?`Updated ${fmtDate(pack.updated)}`:'Open exact project'))}</em></span>${icon('external')}</button>`).join('')}</div>${c.creatorModpacksError?`<div class="creator-profile-warning">Some provider scans could not refresh; last-known-good packs remain visible: ${esc(c.creatorModpacksError)}</div>`:''}</details>`}
function creatorChannelCard(c){const av=safeImg(c.avatarUrl),pct=c.totalVideos?Math.min(100,Math.round((c.analyzedVideos/c.totalVideos)*100)):0,identity=c.handle||c.channelId||c.url,source=c.source||(c.required?'core':'custom'),state=c.paused?'paused':(c.syncStatus||'idle');return `<article class="card creator-channel-card ${c.paused?'paused':''}"><div class="creator-channel-head">${av?`<img src="${esc(av)}" alt="" referrerpolicy="no-referrer">`:`<span class="creator-channel-avatar">${icon('video')}</span>`}<div><div class="creator-channel-title-line"><h3>${esc(c.title||c.handle||c.channelId||'Creator')}</h3><span class="creator-source-badge ${esc(source)}">${esc(String(c.platform||'youtube').toUpperCase())} · ${esc(source)}</span></div><a href="#" data-open="${esc(c.url)}">${esc(identity)}</a></div><span class="creator-sync-state ${esc(state)}">${esc(state==='paused'?'auto-sync paused':state||'not synced')}</span></div><progress class="creator-channel-progress" max="100" value="${pct}" aria-label="${pct}% of indexed videos analyzed">${pct}%</progress><div class="creator-channel-numbers"><span><b>${fmtNum(c.indexedVideos)}</b> indexed</span><span><b>${fmtNum(c.analyzedVideos)}</b> analyzed</span><span><b>${fmtNum(c.shorts)}</b> short-form</span><span><b>${fmtNum(c.recommendations)}</b> mods</span><span><b>${fmtNum((c.creatorModpacks||[]).length)}</b> packs</span></div>${creatorModpacksHTML(c)}${creatorProfileLinksHTML(c)}${c.syncError?`<div class="creator-channel-error">${esc(c.syncError)}</div>`:''}<div class="creator-channel-tools"><button class="btn small" data-sync-channel="${esc(c.url)}">${icon('refresh')} Full rescan</button><button class="btn small" data-refresh-profile-links="${esc(c.url)}">${icon('globe')} Refresh links + packs</button><button class="btn small" data-pause-channel="${esc(c.url)}" data-paused="${c.paused?'true':'false'}">${icon(c.paused?'power':'pause')} ${c.paused?'Resume auto-sync':'Pause auto-sync'}</button><button class="btn small" data-open="${esc(c.url)}">${icon('external')} Channel</button>${c.required?'':`<button class="btn small danger" data-remove-channel="${esc(c.url)}">${icon('trash')} Unfollow</button>`}<span class="creator-channel-date">${c.lastSyncedAt?`Last sync ${esc(fmtDate(c.lastSyncedAt))}`:'Waiting for first full sync'}${c.addedAt?` · followed ${esc(fmtDate(c.addedAt))}`:''}</span></div></article>`}
async function refreshCreatorProfileLinksUI(raw,button){const old=button?.innerHTML;if(button){button.disabled=true;button.textContent='Refreshing links…'}try{const data=await api('/api/creators/channels/links/refresh',{method:'POST',body:JSON.stringify({url:raw})});showToast(`Refreshed ${data.count||0} creator link${data.count===1?'':'s'} and ${data.modpackCount||0} verified modpack${data.modpackCount===1?'':'s'}.`);await loadCreatorChannels()}catch(err){showToast(err.message,true);await loadCreatorChannels()}finally{if(button){button.disabled=false;button.innerHTML=old}}}
function renderCreatorArchiveStats(){const indexed=creatorChannels.reduce((n,c)=>n+(c.indexedVideos||0),0),analyzed=creatorChannels.reduce((n,c)=>n+(c.analyzedVideos||0),0),shorts=creatorChannels.reduce((n,c)=>n+(c.shorts||0),0),mods=creatorChannels.reduce((n,c)=>n+(c.recommendations||0),0),pending=creatorChannels.reduce((n,c)=>n+(c.pendingVideos||0),0);document.getElementById('creatorArchiveStats').innerHTML=[['Videos indexed',indexed],['Analyzed',analyzed],['Short-form',shorts],['Mod recommendations',mods],['Pending analysis',pending]].map(([l,v])=>`<div class="card creator-stat"><b>${fmtNum(v)}</b><span>${esc(l)}</span></div>`).join('')}
async function addCreatorChannel(raw,button){raw=String(raw||document.getElementById('creatorChannelInput')?.value||'').trim();const status=document.getElementById('creatorAddStatus');if(!raw){showToast('Paste a YouTube/TikTok creator URL, @handle, or YouTube channel ID.',true);document.getElementById('creatorChannelInput')?.focus();return}const b=button||document.getElementById('addCreatorChannel'),old=b?.innerHTML;if(b){b.disabled=true;b.textContent='Following + indexing…'}if(status)status.textContent='Saving creator and starting a resumable full-history archive…';try{const data=await api('/api/creators/channels',{method:'POST',body:JSON.stringify({url:raw,sync:true,analyze:true})});const added=(data.added||[])[0],existing=(data.existing||[])[0],ch=added||existing;if(document.getElementById('creatorChannelInput')&&!button)document.getElementById('creatorChannelInput').value='';if(status)status.textContent=`${added?'Following':'Already following'} ${ch?.title||ch?.handle||ch?.channelId||raw}. ${data.started?'Full-history sync started; later refreshes stay incremental.':'Archive is already active or queued.'}`;showToast(`${added?'Following':'Already following'} ${ch?.title||ch?.handle||ch?.channelId||raw}.`);await loadCreatorChannels();setTimeout(()=>{loadCreatorChannels();loadCreatorArchive()},900)}catch(err){if(status)status.textContent=err.message;showToast(err.message,true)}finally{if(b){b.disabled=false;b.innerHTML=old}}}
async function addCreatorTopPicks(button){const b=button||document.getElementById('addCreatorTopPicks'),old=b.innerHTML,urls=creatorSuggestions.filter(s=>!s.tracked&&(s.priority||0)>=90).map(s=>s.url);if(!urls.length){showToast('All curated creator picks are built in and already followed.');return}b.disabled=true;b.textContent=`Adding ${urls.length} creators…`;try{const data=await api('/api/creators/channels',{method:'POST',body:JSON.stringify({urls,sync:true,analyze:true})});showToast(`Added ${data.added?.length||0} creator${data.added?.length===1?'':'s'} and started ${data.started||0} full-history sync${data.started===1?'':'s'}.`);await loadCreatorChannels();setTimeout(()=>loadCreatorArchive(),900)}catch(err){showToast(err.message,true)}finally{b.disabled=false;b.innerHTML=old}}
async function setCreatorChannelPaused(raw,paused,button){const old=button?.innerHTML;if(button){button.disabled=true;button.textContent=paused?'Pausing…':'Resuming…'}try{const data=await api('/api/creators/channels',{method:'PATCH',body:JSON.stringify({url:raw,paused})});showToast(`${data.channel?.title||data.channel?.handle||'Creator'} automatic refresh ${paused?'paused':'resumed'}. The existing archive is preserved.`);await loadCreatorChannels()}catch(err){showToast(err.message,true)}finally{if(button){button.disabled=false;button.innerHTML=old}}}
async function removeCreatorChannel(raw,button){const ch=creatorChannels.find(c=>c.url===raw),label=ch?.title||ch?.handle||'this creator';if(!confirm(`Unfollow ${label}?\n\nAlready indexed videos, transcripts and mod recommendations stay in the Vault. Only automatic tracking stops.`))return;const old=button?.innerHTML;if(button){button.disabled=true;button.textContent='Unfollowing…'}try{await api(`/api/creators/channels?url=${encodeURIComponent(raw)}`,{method:'DELETE'});showToast(`Unfollowed ${label}. Indexed archive preserved.`);await loadCreatorChannels();await loadCreatorArchive()}catch(err){showToast(err.message,true)}finally{if(button){button.disabled=false;button.innerHTML=old}}}
async function syncCreatorArchive(channel='',button){const b=button||document.getElementById('syncCreatorArchive'),old=b.innerHTML;b.disabled=true;b.textContent=channel?'Rescanning channel…':'Starting active-channel sync…';try{const data=await api('/api/creators/channels/sync',{method:'POST',body:JSON.stringify({url:channel,full:true,analyze:true})});showToast(`Started ${data.started} complete creator sync${data.started===1?'':'s'}. Indexing, speech transcription and visual OCR continue resumably.`);setTimeout(()=>{loadCreatorChannels();loadCreatorArchive()},1000)}catch(err){showToast(err.message,true)}finally{b.disabled=false;b.innerHTML=old}}
async function reloadCreatorCatalogsUI(button){const b=button||document.getElementById('reloadCreatorCatalogs'),old=b?.innerHTML;if(b){b.disabled=true;b.textContent='Reloading catalogs…'}try{const data=await api('/api/creators/catalogs/reload',{method:'POST'}),c=data.catalogs||0,v=data.videos||0,r=data.recommendations||0,e=(data.errors||[]).length;showToast(`Catalogs reloaded: ${fmtNum(c)} bundles · ${fmtNum(v)} videos · ${fmtNum(r)} recommendations${e?` · ${e} warning${e===1?'':'s'}`:''}.`,e>0);await loadCreatorChannels();await loadCreatorArchive()}catch(err){showToast(err.message,true)}finally{if(b){b.disabled=false;b.innerHTML=old}}}
async function loadCreatorArchive(){if(creatorArchiveView==='videos')return loadCreatorVideos();return loadCreatorRecommendations()}
async function loadCreatorRecommendations(){const root=document.getElementById('creatorRecommendationGrid'),videos=document.getElementById('creatorGrid'),status=document.getElementById('creatorStatus');root.hidden=false;videos.hidden=true;try{const data=await api('/api/creators/recommendations?'+creatorArchiveParams('mods'));status.textContent=`${fmtNum(data.count)} resolved recommendations · evidence from descriptions, links, speech transcripts and on-screen text`;root.innerHTML=(data.recommendations||[]).map(creatorRecommendationCard).join('')||'<div class="card empty">No recommendations match these filters yet. If the first sync is still running, the archive fills continuously as videos finish analysis.</div>';wireCreatorCards(root)}catch(err){status.textContent=err.message;root.innerHTML=`<div class="card empty">${esc(err.message)}</div>`}}
function creatorRecommendationCard(r){const m=r.mod||{},mi=safeImg(m.iconUrl),thumb=safeImg(r.videoThumbnailUrl),key=m.provider?cacheProject({provider:m.provider,id:m.projectId||m.name,slug:m.projectId||'',title:m.name,summary:m.projectSummary,author:m.author,iconUrl:m.iconUrl,pageUrl:m.url,projectType:m.projectType||'mod'}):'',sources=(m.sourceKinds||[]).map(x=>`<span>${esc(x)}</span>`).join(''),context=m.descriptionContext||m.transcriptContext||m.evidence||'';return `<article class="card creator-rec-card"><div class="creator-rec-media">${thumb?`<img src="${esc(thumb)}" alt="" loading="lazy" referrerpolicy="no-referrer">`:`<span>${icon('video')}</span>`}<div><span class="creator-kind-badge">${esc(r.videoKind||'video')}</span><b>${esc(r.videoTitle||'Untitled video')}</b><small>${esc(r.channelTitle||r.channelHandle)} · ${esc(fmtDate(r.videoPublishedAt))}</small></div></div><div class="creator-rec-main"><div class="creator-rec-mod">${mi?`<img src="${esc(mi)}" alt="" loading="lazy" referrerpolicy="no-referrer">`:`<span>${icon(m.projectType==='resourcepack'?'pack':'mod')}</span>`}<div><h3>${esc(m.name)}</h3><small>${esc(m.author||'Unknown author')} · ${esc(providerName(m.provider||'source'))} · ${Math.round((m.confidence||0)*100)}% confidence</small></div></div>${m.projectSummary?`<p class="creator-project-summary">${esc(m.projectSummary)}</p>`:''}${context?`<div class="creator-evidence"><b>Why it was detected</b><p>${esc(context)}</p><div class="creator-evidence-sources">${sources}</div></div>`:''}<div class="project-actions"><button class="btn primary small" data-open="${esc(m.videoLink||r.videoUrl)}">${esc(m.timestamp||'0:00')} in video</button>${key?`<button class="btn small" data-project-details="${esc(key)}">Mod in Vault</button>`:`<button class="btn small" data-creator-search="${esc(m.name)}">Find Mod</button>`}<button class="btn small" data-transcript-video="${esc(r.videoId)}" data-video-title="${esc(r.videoTitle)}">Transcript</button></div></div></article>`}
async function loadCreatorVideos(){const root=document.getElementById('creatorGrid'),recs=document.getElementById('creatorRecommendationGrid'),status=document.getElementById('creatorStatus');root.hidden=false;recs.hidden=true;try{const data=await api('/api/creators/videos?'+creatorArchiveParams('videos'));status.textContent=`${fmtNum(data.count)} videos shown · ${fmtNum(data.pending)} waiting for analysis${data.failed?` · ${fmtNum(data.failed)} retrying/needs review`:''}`;root.innerHTML=(data.videos||[]).map(creatorCard).join('')||'<div class="card empty">No videos match these filters.</div>';wireCreatorCards(root)}catch(err){status.textContent=err.message;root.innerHTML=`<div class="card empty">${esc(err.message)}</div>`}}
function creatorCard(v){const thumb=safeImg(v.thumbnailUrl),avatar=safeImg(v.creatorAvatarUrl),warnings=(v.warnings||[]),unresolved=(v.unresolvedMentions||[]),pending=!v.analyzedAt;const resolved=(v.mods||[]).map(m=>{const mi=safeImg(m.iconUrl),key=m.provider?cacheProject({provider:m.provider,id:m.projectId||m.name,slug:m.projectId||'',title:m.name,summary:m.projectSummary,author:m.author,iconUrl:m.iconUrl,pageUrl:m.url,projectType:m.projectType||'mod'}):'';return `<div class="creator-mod"><button class="btn small timestamp" data-open="${esc(m.videoLink||v.url)}">${esc(m.timestamp||'0:00')}</button><div class="creator-mod-icon">${mi?`<img src="${esc(mi)}" alt="" loading="lazy" referrerpolicy="no-referrer">`:icon(m.projectType==='resourcepack'?'pack':'mod')}</div><div><b>${esc(m.name)}</b><small>${esc(m.author||'Unknown author')} · ${esc(m.provider||'source')} · ${Math.round((m.confidence||0)*100)}%</small><small>${esc(m.projectSummary||m.descriptionContext||m.transcriptContext||m.evidence||'')}</small></div>${key?`<button class="btn small" data-project-details="${esc(key)}">Mod in Vault</button>`:`<button class="btn small" data-creator-search="${esc(m.name)}">Find Mod</button>`}</div>`}).join('');const review=unresolved.length?`<div class="creator-review-heading"><b>${unresolved.length} transcript mention${unresolved.length===1?'':'s'} need review</b><small>Kept instead of silently dropping a possible mod.</small></div>${unresolved.map(m=>`<div class="creator-mod unresolved"><button class="btn small timestamp" data-open="${esc(m.videoLink||v.url)}">${esc(m.timestamp||'0:00')}</button><div class="creator-mod-icon">${icon('search')}</div><div><b>${esc(m.name)}</b><small>${esc(m.evidence||'Unresolved transcript mention')}</small></div><button class="btn small" data-creator-search="${esc(m.name)}">Search Mods</button></div>`).join('')}`:'';return `<article class="card creator-card ${pending?'creator-pending':''}"><div class="creator-hero">${thumb?`<img src="${esc(thumb)}" alt="" loading="lazy" referrerpolicy="no-referrer">`:`<div class="fallback-art">${icon('video')}</div>`}<span class="creator-platform">${esc(v.videoKind||v.platform)}</span><div class="creator-title"><div class="creator-identity">${avatar?`<img class="creator-avatar" src="${esc(avatar)}" alt="" loading="lazy" referrerpolicy="no-referrer">`:`<span class="creator-avatar fallback">${icon('video')}</span>`}<div><h3>${esc(v.title||'Untitled creator video')}</h3><span>${esc(v.creator||v.channelHandle||'Unknown creator')} · ${esc(fmtDate(v.publishedAt))}${v.durationSeconds?` · ${esc(fmtDuration(v.durationSeconds))}`:''}</span></div></div></div></div><div class="creator-body"><div class="creator-meta"><span>${pending?`Queued${v.analysisError?' · retry pending':''}`:v.transcriptAvailable?`Transcript: ${esc(v.transcriptSource||'available')} · ${fmtNum(v.transcriptWords||0)} words`:'Description indexed'}</span><span>${(v.mods||[]).length} resolved mods${unresolved.length?` · ${unresolved.length} review`:''}</span></div>${v.description?`<details class="creator-description"><summary>Video description</summary><p>${esc(v.description)}</p></details>`:''}${v.analysisError?`<div class="creator-channel-error">${esc(v.analysisError)}</div>`:''}${warnings.length?`<div class="creator-warnings">${warnings.slice(0,3).map(x=>`<span>${esc(x)}</span>`).join('')}</div>`:''}<div class="creator-mods">${resolved||(!review&&!pending?'<div class="empty">Analysis completed, but no mod mentions could be confidently resolved.</div>':'')}${review}</div><div class="project-actions"><button class="btn small" data-open="${esc(v.url)}">${icon('video')} Video</button>${v.transcriptAvailable?`<button class="btn small" data-transcript-video="${esc(v.id)}" data-video-title="${esc(v.title)}">Transcript</button>`:''}<button class="btn small" data-analyze-url="${esc(v.url)}">${icon('sparkle')} ${pending?'Analyze now':'Refresh analysis'}</button></div></div></article>`}
function wireCreatorCards(root){root.querySelectorAll('[data-open]').forEach(b=>b.onclick=e=>{e.preventDefault();openExternal(b.dataset.open)});root.querySelectorAll('[data-project-details]').forEach(b=>b.onclick=()=>openProjectDetails(b.dataset.projectDetails));root.querySelectorAll('[data-analyze-url]').forEach(b=>b.onclick=()=>analyzeCreatorURL(b.dataset.analyzeUrl,b));root.querySelectorAll('[data-creator-search]').forEach(b=>b.onclick=()=>{document.getElementById('modQuery').value=b.dataset.creatorSearch;activeCategory='all';renderCategoryStrip();navigate('mods');modsSearch()});root.querySelectorAll('[data-transcript-video]').forEach(b=>b.onclick=()=>openCreatorTranscript(b.dataset.transcriptVideo,b.dataset.videoTitle))}
async function openCreatorTranscript(videoId,title){const modal=document.getElementById('creatorTranscriptModal'),body=document.getElementById('creatorTranscriptBody');modal.classList.add('open');modal.setAttribute('aria-hidden','false');body.innerHTML='<div class="loading">Loading timed transcript…</div>';try{const t=await api(`/api/creators/transcript?videoId=${encodeURIComponent(videoId)}`);body.innerHTML=`<span class="eyebrow">TIMED TRANSCRIPT</span><h2>${esc(title||videoId)}</h2><div class="creator-transcript-meta">${esc(t.source||'unknown source')} · ${fmtNum(t.segmentCount)} segments · ${fmtNum(t.wordCount)} words</div><div class="creator-transcript-search search-field"><span>${icon('search')}</span><input id="creatorTranscriptSearch" placeholder="Search inside transcript…"></div><div class="creator-transcript-segments" id="creatorTranscriptSegments">${(t.segments||[]).map(x=>transcriptSegmentHTML(videoId,x)).join('')}</div>`;document.getElementById('creatorTranscriptSearch').oninput=e=>filterTranscriptSegments(e.target.value)}catch(err){body.innerHTML=`<div class="empty">${esc(err.message)}</div>`}}
function transcriptSegmentHTML(videoId,x){return `<button class="creator-transcript-line" data-transcript-text="${esc(String(x.text||'').toLowerCase())}" data-open="https://www.youtube.com/watch?v=${esc(videoId)}&t=${Math.max(0,Math.floor((Number(x.startMs)||0)/1000))}s"><time>${esc(x.timestamp||'0:00')}</time><span>${esc(x.text||'')}</span></button>`}
