  const mode=document.getElementById('portingSourceMode');if(mode)mode.value='binary';
  const project=document.getElementById('portingProjectName');if(project){const name=String(path||'').split(/[\\/]/).pop().replace(/\.jar(?:\.disabled)?$/i,'');project.value=`${name||'minecraft-mod'}-port`}
