async function loadPortingAtlas(force=false){
  const grid=document.getElementById('portingVersionGrid'),status=document.getElementById('portingVersionStatus');if(!grid||!status)return;
  const query=document.getElementById('portingVersionQuery')?.value.trim()||'',type=document.getElementById('portingVersionType')?.value||'all';
  if(!force&&portingAtlasPayload&&!query&&type==='all'){renderPortingAtlas(portingAtlasPayload);return}
  status.textContent='Reading embedded official version evidence…';grid.innerHTML='<div class="card loading">Indexing Mojang and loader metadata…</div>';
  const params=new URLSearchParams({limit:'1000',evidence:'1'});if(query)params.set('q',query);if(type!=='all')params.set('type',type);
  try{const data=await api(`/api/porting/atlas?${params}`);if(!query&&type==='all')portingAtlasPayload=data;renderPortingAtlas(data)}catch(err){status.textContent=err.message;grid.innerHTML=`<div class="card empty">${esc(err.message)}</div>`}
}
function renderPortingAtlas(data){
  const summary=data.summary||{},versions=data.versions||[];
  document.getElementById('portingAtlasHeadline').textContent=`${fmtNum(summary.minecraftVersions||0)} official versions · ${summary.latestRelease||'unknown'} release · ${summary.latestSnapshot||'unknown'} snapshot`;
  document.getElementById('portingAtlasEvidence').textContent=`Evidence snapshot ${data.evidenceSnapshotAt||'unknown'} · ${fmtNum(data.sourceEvidence?.length||0)} immutable source snapshots · ${fmtNum(summary.clientMappings||0)} client mapping artifacts · ${fmtNum(summary.fabricGameVersions||0)} Fabric and ${fmtNum(summary.quiltGameVersions||0)} Quilt game-version records.`;
  const stats=[['Official manifests',summary.minecraftVersions||0],['Latest release',summary.latestRelease||'?'],['Latest snapshot',summary.latestSnapshot||'?'],['Mapping artifacts',summary.clientMappings||0],['Forge coordinates',data.forge?.count||0],['NeoForge coordinates',data.neoForge?.count||0]];
  document.getElementById('portingAtlasStats').innerHTML=stats.map(([label,value])=>`<div class="porting-atlas-stat"><b>${esc(value)}</b><span>${esc(label)}</span></div>`).join('');
  document.getElementById('portingVersionStatus').textContent=`${fmtNum(data.totalMatches||versions.length)} matching records · all ${fmtNum(versions.length)} returned records are loaded`;
  const list=document.getElementById('portingVersionList');if(list&&(!portingAtlasPayload||data===portingAtlasPayload||list.children.length===0))list.innerHTML=versions.map(v=>`<option value="${esc(v.id)}">${esc(v.type)} · Java ${esc(v.javaMajor||'?')}</option>`).join('');
  document.getElementById('portingVersionGrid').innerHTML=versions.length?versions.map(portingVersionCard).join(''):'<div class="card empty">No official version records match this search.</div>';
  wirePortingVersionCards();
}
