  return `<article class="card porting-version-card"><div class="doctor-card-head"><h4>${esc(v.id)}</h4><span class="tag">${esc(v.type)}</span></div><div class="porting-version-core"><b>Java ${esc(v.javaMajor||'?')}</b><span>${v.releaseTime?esc(new Date(v.releaseTime).toLocaleDateString()):'unknown date'}</span></div><div class="porting-version-schema"><span>Protocol ${esc(v.protocolVersion??'?')}</span><span>Data ${esc(v.dataPackVersion??'?')}</span><span>Resources ${esc(v.resourcePackVersion??'?')}</span></div><div class="doctor-risk-list">${capabilities.map(x=>`<span>${esc(x)}</span>`).join('')}</div><button class="btn small" data-porting-target="${esc(v.id)}">${icon('compass')} Use as target</button></article>`
