  const inputPanel=input?renderPortingInputAnalysis(input):'';
  const tools=(plan.tools||[]).map(tool=>`<article class="card porting-tool-card"><div class="doctor-card-head"><div><span class="tag">${esc(tool.category)}</span><span class="tag maturity-${esc(tool.maturity)}">${esc(tool.maturity)}</span></div>${tool.required?'<span class="tag source">selected</span>':''}</div><h4>${esc(tool.name)}</h4>${tool.pinnedVersion?`<code>${esc(tool.pinnedVersion)}</code>`:''}<p>${esc(tool.reason)}</p>${tool.guardrail?`<p class="doctor-evidence"><b>Guardrail:</b> ${esc(tool.guardrail)}</p>`:''}<button class="btn small" data-porting-open="${esc(tool.officialUrl)}">${icon('external')} Official source</button></article>`).join('');
