  try{const data=await api(`/api/porting/environment?target=${encodeURIComponent(target)}`);root.innerHTML=`<div class="porting-ready ${data.readyForLocalBuild?'ready':'warning'}"><b>${data.readyForLocalBuild?'Local build essentials ready':'Planning ready · build prerequisites incomplete'}</b><span>${data.targetGameVersion?`Target ${esc(data.targetGameVersion)} requests Java ${esc(data.requiredJava||'?')}`:'Choose a target version'}</span></div><div class="porting-command-list">${(data.commands||[]).map(tool=>`<div><i class="state-dot ${tool.installed?'':'off'}"></i><span><b>${esc(tool.id)}</b><small>${esc(tool.version||tool.purpose)}</small></span><code>${tool.installed?'ready':tool.required?'required':'optional'}</code></div>`).join('')}</div>${(data.warnings||[]).map(x=>`<p class="doctor-evidence">${esc(x)}</p>`).join('')}`
  }catch(err){root.innerHTML=`<div class="empty">${esc(err.message)}</div>`}
