async function loadTranscriptionStatus(){const el=document.getElementById('transcriptionStatus');if(!el)return;try{const s=await api('/api/transcription/status');el.classList.toggle('ready',!!s.ready);el.textContent=s.ready?`Ready · yt-dlp · FFmpeg · ${s.modelName} · Whisper.cpp · visual OCR ${s.visualOcr?`(${s.visualOcrBackend||'ready'})`:'unavailable'}`:`On-demand bootstrap · yt-dlp ${s.ytDlp?'ready':'needed'} · FFmpeg ${s.ffmpeg?'ready':'needed'} · Whisper ${s.whisper&&s.model?'ready':'needed'} · visual OCR ${s.visualOcr?(s.visualOcrBackend||'ready'):'needed'}`;const b=document.getElementById('prepareTranscription');if(b){b.disabled=!!s.ready;b.innerHTML=s.ready?`${icon('shield')} Transcript engine ready`:`${icon('download')} Prepare transcript engine`}}catch(err){el.textContent=`Transcript status unavailable: ${err.message}`}}
async function prepareTranscription(){const b=document.getElementById('prepareTranscription'),old=b.innerHTML;b.disabled=true;b.textContent='Downloading and verifying transcript tools…';try{await api('/api/transcription/prepare',{method:'POST',body:'{}'});await loadTranscriptionStatus();showToast('Local archival transcript engine is ready for captionless videos.')}catch(err){b.disabled=false;b.innerHTML=old;showToast(err.message,true)}}
function configureCreatorSort(){const sel=document.getElementById('creatorArchiveSort');if(!sel)return;const previous=sel.value;const options=creatorArchiveView==='videos'?[['published-desc','Newest videos first'],['published-asc','Oldest videos first'],['mods-desc','Videos with most mods'],['mods-asc','Videos with fewest mods'],['title','Video title A–Z']]:[['recommended-desc','Latest recommended first'],['recommended-asc','Oldest recommended first'],['name','Mod name A–Z'],['channel','Channel'],['confidence','Highest confidence'],['video-desc','Newest videos first'],['video-asc','Oldest videos first']];sel.innerHTML=options.map(([v,l])=>`<option value="${v}">${l}</option>`).join('');if(options.some(([v])=>v===previous))sel.value=previous}
function setCreatorArchiveView(view){creatorArchiveView=view==='videos'?'videos':'mods';document.getElementById('creatorModsView').classList.toggle('active',creatorArchiveView==='mods');document.getElementById('creatorVideosView').classList.toggle('active',creatorArchiveView==='videos');configureCreatorSort();loadCreatorArchive()}
function scheduleCreatorArchiveRefresh(){clearTimeout(creatorArchiveDebounce);creatorArchiveDebounce=setTimeout(loadCreatorArchive,180)}

async function installProject(projectId,target,button){const old=button?.innerHTML;if(button){button.disabled=true;button.textContent='Installing…'}try{const result=await api('/api/modrinth/install',{method:'POST',body:JSON.stringify({projectId,gameVersion:currentSettings?.gameVersion,loader:currentSettings?.loader,target:target==='resourcepack'?'resourcepacks':target==='shader'?'shaderpacks':'mods'})});showToast(`Installed ${result.project} ${result.version}`)}catch(err){showToast(err.message,true)}finally{if(button){button.disabled=false;button.innerHTML=old}}}
async function installCitEngine(){let project='cit-resewn';if(/^(26\.|1\.21\.(?:1[0-9]|[2-9][0-9]))/.test(currentSettings?.gameVersion||''))project='cit-resewn-continuation';try{const result=await api('/api/modrinth/install',{method:'POST',body:JSON.stringify({projectId:project,gameVersion:currentSettings?.gameVersion,loader:currentSettings?.loader,target:'mods'})});showToast(`Installed ${result.project}`)}catch(err){showToast(err.message,true)}}

async function refreshManager(options){
  if(window.OmniManager&&typeof OmniManager.refresh==='function')return OmniManager.refresh(options||{});
  const root=document.getElementById('managerGroups');
  if(root)root.innerHTML='<div class="card empty">OmniManager failed to load. Reload the packaged application.</div>';
}

function pathForKind(kind){if(!currentSettings)return'';if(kind==='mods')return`${currentSettings.javaRoot}/mods`;if(kind==='resourcepacks')return`${currentSettings.javaRoot}/resourcepacks`;if(kind==='shaderpacks')return`${currentSettings.javaRoot}/shaderpacks`;if(kind==='plugins')return currentSettings.serverRoot?`${currentSettings.serverRoot}/plugins`:`${currentSettings.javaRoot}/plugins`;if(kind==='datapacks')return currentSettings.worldRoot?`${currentSettings.worldRoot}/datapacks`:systemInfo?.configDir?`${systemInfo.configDir}/downloads`:'';return systemInfo?.configDir?`${systemInfo.configDir}/downloads`:''}
async function toggleManagedFile(path){try{await api('/api/file/toggle',{method:'POST',body:JSON.stringify({path})});refreshManager()}catch(err){showToast(err.message,true)}}
async function trashManagedFile(path){try{await api('/api/file/trash',{method:'POST',body:JSON.stringify({path})});showToast('Moved to Vault trash.');refreshManager()}catch(err){showToast(err.message,true)}}
async function importFiles(files){if(!files?.length)return;const form=new FormData();for(const file of files)form.append('files',file,file.name);form.append('target',document.getElementById('importTarget').value);const root=document.getElementById('importResults');root.innerHTML='<div class="card loading">Importing packages…</div>';try{const data=await api('/api/import',{method:'POST',body:form});root.innerHTML=data.results.map(r=>`<div class="card import-result"><div><b>${esc(r.name)}</b><small>${r.ok?`${esc(r.target)} · ${esc(r.path||'')}`:esc(r.error||'Import failed')}</small></div><span class="${r.ok?'ok-text':'bad-text'}">${r.ok?'Imported':'Failed'}</span></div>`).join('');showToast(`Imported ${data.results.filter(r=>r.ok).length} of ${data.results.length}.`)}catch(err){root.innerHTML=`<div class="card empty">${esc(err.message)}</div>`;showToast(err.message,true)}}

async function loadProviders(){
  try{const data=await api('/api/providers');providerCatalog=data.providers||[];providerHealth=data.health||{};for(const k of Object.keys(PROVIDER_NAMES))delete PROVIDER_NAMES[k];for(const p of providerCatalog)PROVIDER_NAMES[p.id]=p.name;renderProviderStrip();renderSources();renderSourceSettings();renderHomeStats()}catch(err){showToast(`Provider registry unavailable: ${err.message}`,true)}
}
function renderSources(){
  const grid=document.getElementById('sourceGrid');if(!grid)return;
  grid.innerHTML=providerCatalog.map(p=>{const h=providerHealth[p.id]||{},ready=providerReady(p);return `<article class="card provider-card"><div class="provider-card-head"><div class="item-icon blue">${icon(providerTypeIcon(p))}</div><div><h3>${esc(p.name)}</h3><div class="meta"><span class="tag source">${esc(p.group)}</span><span class="tag">${esc(p.searchMode)}</span><span class="tag">${esc(p.detailMode)}</span></div></div><i class="provider-health large ${esc(h.status||'idle')}"></i></div><div class="desc">${esc(p.description)}</div><div class="capability-list">${(p.capabilities||[]).map(x=>`<span>${esc(x)}</span>`).join('')}</div><div class="provider-status-row"><span>${ready?'Ready to query':`Needs ${esc(p.credential||'credential')} key`}</span><span>${h.lastResultCount!=null&&h.status==='ok'?`${h.lastResultCount} last results`:h.lastError?esc(h.lastError):'Not queried this session'}</span></div><div class="item-actions"><button class="btn primary small" data-source-browse="${esc(p.id)}">${icon('search')} Search ${esc(p.name)} inside Vault</button></div></article>`}).join('')||'<div class="card empty">Provider registry is loading.</div>';
  grid.querySelectorAll('[data-source-browse]').forEach(b=>b.onclick=()=>{activeProviders=new Set([b.dataset.sourceBrowse]);renderProviderStrip();navigate('mods');modsSearch()});
}

function renderSourceSettings(){const root=document.getElementById('sourceSettings');if(!root)return;let group='';const out=[];for(const p of providerCatalog){if(p.group!==group){group=p.group;out.push(`<div class="source-settings-group">${esc(group)}</div>`)}out.push(`<label class="source-check"><input type="checkbox" value="${esc(p.id)}" ${currentSettings?.enabledSources?.includes(p.id)?'checked':''}> <span>${esc(p.name)}</span>${p.credential&&!p.credentialConfigured?`<small>key required</small>`:''}</label>`)}root.innerHTML=out.join('')}
async function loadSettings(){try{currentSettings=await api('/api/settings');const set=(id,v)=>{const e=document.getElementById(id);if(e)e.value=v??''};set('javaRoot',currentSettings.javaRoot);set('bedrockRoot',currentSettings.bedrockRoot);set('bedrockPreviewRoot',currentSettings.bedrockPreviewRoot);set('bedrockCustomRoots',(currentSettings.bedrockCustomRoots||[]).join('\n'));set('worldRoot',currentSettings.worldRoot);set('serverRoot',currentSettings.serverRoot);set('serverPlatform',currentSettings.serverPlatform||'PAPER');set('gameVersion',currentSettings.gameVersion);set('loader',currentSettings.loader);set('activeProfile',currentSettings.activeProfile);set('curseForgeAPIKey',currentSettings.curseForgeApiKey);set('githubToken',currentSettings.githubToken);set('builtByBitAPIKey',currentSettings.builtByBitApiKey);set('builtByBitOAuthToken',currentSettings.builtByBitOAuthToken);set('nexusAPIKey',currentSettings.nexusApiKey);set('youtubeAPIKey',currentSettings.youtubeApiKey);set('autoRefreshMinutes',currentSettings.autoRefreshMinutes||15);set('creatorRefreshMinutes',currentSettings.creatorRefreshMinutes||60);set('creatorTranscriptModel',currentSettings.creatorTranscriptModel||'large-v3-turbo-q5_0');set('creatorArchiveConcurrency',currentSettings.creatorArchiveConcurrency||2);set('preferredTags',(currentSettings.preferredTags||[]).join(', '));set('modGameVersion',currentSettings.gameVersion||'1.21.1');set('modLoader',['fabric','forge','neoforge','quilt'].includes(currentSettings.loader)?currentSettings.loader:'any');activeProviders=new Set(currentSettings.enabledSources||providerCatalog.filter(p=>p.defaultEnabled).map(p=>p.id));renderProviderStrip();renderSourceSettings();syncUpdaterTargets();syncDoctorTargets();syncPortingTargets();renderSystemPanel()}catch(err){showToast(err.message,true)}}
async function saveSettings(e){e.preventDefault();const payload={javaRoot:document.getElementById('javaRoot').value.trim(),bedrockRoot:document.getElementById('bedrockRoot').value.trim(),bedrockPreviewRoot:document.getElementById('bedrockPreviewRoot').value.trim(),bedrockCustomRoots:document.getElementById('bedrockCustomRoots').value.split(/\r?\n/).map(x=>x.trim()).filter(Boolean),worldRoot:document.getElementById('worldRoot').value.trim(),serverRoot:document.getElementById('serverRoot').value.trim(),serverPlatform:document.getElementById('serverPlatform').value,gameVersion:document.getElementById('gameVersion').value.trim(),loader:document.getElementById('loader').value,activeProfile:document.getElementById('activeProfile').value.trim(),curseForgeApiKey:document.getElementById('curseForgeAPIKey').value.trim(),githubToken:document.getElementById('githubToken').value.trim(),builtByBitApiKey:document.getElementById('builtByBitAPIKey').value.trim(),builtByBitOAuthToken:document.getElementById('builtByBitOAuthToken').value.trim(),nexusApiKey:document.getElementById('nexusAPIKey').value.trim(),youtubeApiKey:document.getElementById('youtubeAPIKey').value.trim(),providerSchemaVersion:currentSettings?.providerSchemaVersion||1,autoRefreshMinutes:Number(document.getElementById('autoRefreshMinutes').value)||15,creatorRefreshMinutes:Number(document.getElementById('creatorRefreshMinutes').value)||60,creatorTranscriptModel:document.getElementById('creatorTranscriptModel').value||'large-v3-turbo-q5_0',creatorArchiveConcurrency:Math.max(1,Math.min(4,Number(document.getElementById('creatorArchiveConcurrency').value)||2)),preferredTags:document.getElementById('preferredTags').value.split(',').map(x=>x.trim()).filter(Boolean),enabledSources:[...document.querySelectorAll('#sourceSettings input:checked')].map(x=>x.value)};try{currentSettings=await api('/api/settings',{method:'POST',body:JSON.stringify(payload)});await loadProviders();activeProviders=new Set(currentSettings.enabledSources);renderProviderStrip();syncUpdaterTargets();showToast('Settings saved. Provider credentials and refresh loops are active.');systemInfo=await api('/api/system');renderSystemPanel()}catch(err){showToast(err.message,true)}}
function renderSystemPanel(){if(!systemInfo)return;document.getElementById('systemPanel').innerHTML=`<h3>Runtime & intelligence</h3><div class="system-row"><span>App</span><code>${esc(systemInfo.name)} ${esc(systemInfo.version)}</code></div><div class="system-row"><span>Platform</span><code>${esc(systemInfo.os)} / ${esc(systemInfo.arch)}</code></div><div class="system-row"><span>Java root</span><code>${systemInfo.javaExists?'Detected':'Not detected'}</code></div><div class="system-row"><span>Bedrock Stable</span><code>${systemInfo.bedrockExists?'Detected':'Optional / not detected'}</code></div><div class="system-row"><span>Bedrock Preview</span><code>${systemInfo.bedrockPreviewExists?'Detected':'Optional / not detected'}</code></div><div class="system-row"><span>Custom Bedrock roots</span><code>${esc((currentSettings?.bedrockCustomRoots||[]).length)}</code></div><div class="system-row"><span>Server root</span><code>${systemInfo.serverExists?'Detected':'Optional / not detected'} · ${esc(currentSettings?.serverPlatform||'PAPER')}</code></div><div class="system-row"><span>Active world</span><code>${systemInfo.worldExists?'Detected · datapacks enabled':'Optional / not detected'}</code></div><div class="system-row"><span>Recommendation loop</span><code>every ${esc(currentSettings?.autoRefreshMinutes||15)} min</code></div><div class="system-row"><span>Creator loop</span><code>every ${esc(currentSettings?.creatorRefreshMinutes||60)} min</code></div><div class="system-row"><span>Config</span><code>${esc(systemInfo.configDir)}</code></div>`}

