async function init(){try{modViewMode=localStorage.getItem('mmv-mod-view')==='list'?'list':'grid'}catch{}injectIcons();renderNav();renderHomeStats();renderLegacy();wireStatic();configureCreatorSort();try{systemInfo=await api('/api/system');currentSettings=systemInfo.settings;document.getElementById('versionPill').textContent=`v${systemInfo.version}`;document.getElementById('runtimePill').textContent=`${systemInfo.os} ${systemInfo.arch}`;await loadProviders();await loadSettings();await loadTaxonomy();loadRecommendations();loadCreatorChannels();loadCreatorArchive();loadTranscriptionStatus()}catch(err){showToast(`Desktop backend unavailable: ${err.message}`,true)}const hash=location.hash.slice(1);navigate(PAGE_COPY[hash]?hash:(hash==='amazing'||hash==='browser'?'mods':'home'));setInterval(heartbeat,20000);setInterval(()=>{loadRecommendations();loadProviders()},60000);setInterval(()=>{if(document.querySelector('[data-view=creators]')?.classList.contains('active')){loadCreatorChannels();loadCreatorArchive()}},60000);heartbeat()}
